-- Lina Line Fashion Hub & Academy
-- Run this only if the Supabase project does not already contain the schema.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'staff' check (role in ('admin','staff','instructor')), created_at timestamptz not null default now());
create table if not exists public.site_settings (id integer primary key default 1 check(id=1),site_name text not null default 'Lina Line Fashion Hub & Academy',tagline text default 'Where fashion becomes a legacy.',hero_title text default 'Where fashion becomes a legacy.',hero_text text default 'Lina Line combines a distinctive fashion house with practical fashion education.',hero_image text,logo_url text,email text,phone text default '0808935411',address text default 'Shop 6, Jiyamere Plaza, Gombe, Gombe State',admission_open boolean not null default true,admission_title text default 'Admissions are open',admission_text text default 'Applications for the next training intake are now being received.',updated_at timestamptz not null default now());
create table if not exists public.courses (id bigint generated by default as identity primary key,name text not null,description text,duration text,fee numeric(12,2) default 0,image_url text,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.projects (id bigint generated by default as identity primary key,title text not null,student_name text,category text,description text,image_url text,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.events (id bigint generated by default as identity primary key,title text not null,description text,event_date date,event_time text,location text,image_url text,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.applications (id bigint generated by default as identity primary key,full_name text not null,email text,phone text not null,programme text,message text,status text not null default 'pending' check(status in('pending','reviewing','approved','rejected')),created_at timestamptz not null default now());
create table if not exists public.students (id bigint generated by default as identity primary key,full_name text not null,phone text,email text,programme text,admission_date date default current_date,status text not null default 'active' check(status in('active','completed','inactive')),notes text,created_at timestamptz not null default now());
create table if not exists public.payments (id bigint generated by default as identity primary key,student_id bigint references public.students(id) on delete set null,amount numeric(12,2) not null,reference text,payment_date date default current_date,notes text,created_at timestamptz not null default now());
create table if not exists public.achievements (id bigint generated by default as identity primary key,student_id bigint references public.students(id) on delete cascade,title text not null,remark text,created_at timestamptz not null default now());
create table if not exists public.activity_log (id bigint generated by default as identity primary key,message text not null,created_at timestamptz not null default now());
insert into public.site_settings(id) values(1) on conflict(id) do nothing;
alter table public.profiles enable row level security;
alter table public.site_settings enable row level security;
alter table public.courses enable row level security;
alter table public.projects enable row level security;
alter table public.events enable row level security;
alter table public.applications enable row level security;
alter table public.students enable row level security;
alter table public.payments enable row level security;
alter table public.achievements enable row level security;
alter table public.activity_log enable row level security;
create or replace function public.is_staff() returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role in('admin','staff','instructor')); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),'staff') on conflict(id) do nothing; return new; end; $$;
revoke execute on function public.handle_new_user() from public;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
drop policy if exists public_read_settings on public.site_settings; create policy public_read_settings on public.site_settings for select to anon,authenticated using(true);
drop policy if exists staff_manage_settings on public.site_settings; create policy staff_manage_settings on public.site_settings for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists public_read_courses on public.courses; create policy public_read_courses on public.courses for select to anon,authenticated using(published=true or public.is_staff());
drop policy if exists staff_manage_courses on public.courses; create policy staff_manage_courses on public.courses for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists public_read_projects on public.projects; create policy public_read_projects on public.projects for select to anon,authenticated using(published=true or public.is_staff());
drop policy if exists staff_manage_projects on public.projects; create policy staff_manage_projects on public.projects for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists public_read_events on public.events; create policy public_read_events on public.events for select to anon,authenticated using(published=true or public.is_staff());
drop policy if exists staff_manage_events on public.events; create policy staff_manage_events on public.events for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists public_insert_applications on public.applications; create policy public_insert_applications on public.applications for insert to anon,authenticated with check(true);
drop policy if exists staff_read_applications on public.applications; create policy staff_read_applications on public.applications for select to authenticated using(public.is_staff());
drop policy if exists staff_update_applications on public.applications; create policy staff_update_applications on public.applications for update to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists staff_delete_applications on public.applications; create policy staff_delete_applications on public.applications for delete to authenticated using(public.is_staff());
drop policy if exists staff_manage_students on public.students; create policy staff_manage_students on public.students for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists staff_manage_payments on public.payments; create policy staff_manage_payments on public.payments for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists staff_manage_achievements on public.achievements; create policy staff_manage_achievements on public.achievements for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists staff_read_profiles on public.profiles; create policy staff_read_profiles on public.profiles for select to authenticated using(public.is_staff() or id=(select auth.uid()));
grant select on public.site_settings,public.courses,public.projects,public.events to anon,authenticated;
grant insert on public.applications to anon,authenticated;
grant select,insert,update,delete on public.site_settings,public.courses,public.projects,public.events,public.applications,public.students,public.payments,public.achievements,public.activity_log,public.profiles to authenticated;
insert into public.courses(name,description,duration,published) select * from (values ('Fashion Design & Sewing','Build practical skills through guided fashion-making projects.','6 Months',true),('Pattern Drafting','Develop precision, fit and professional pattern-making skills.','3 Months',true),('Advanced Creative Practice','Turn ideas into finished pieces and a stronger portfolio.','4 Months',true)) v(name,description,duration,published) where not exists(select 1 from public.courses);